class PortBoundaryContributionTests(unittest.TestCase):
    def test_port_boundaries_both_apis_and_input_types(self):
        for parse in (urllib.parse.urlsplit, urllib.parse.urlparse,):
            for binary in (False, True):
                for suffix, expected, category in [('', None, 'absent'), (':', None, 'empty'), (':0', 0, 'zero'), (':65535', 65535, 'maximum')]:
                    with self.subTest(api=parse.__name__, binary=binary, category=category):
                        url = 'http://example.test' + suffix + '/'
                        if binary:
                            url = url.encode('ascii')
                        result = parse(url)
                        actual = result.port
                        self.assertEqual(actual, expected)
                        self.assertIs(type(actual), type(expected))

    def test_port_errors_exact_state_and_lazy_timing(self):
        for parse in (urllib.parse.urlsplit, urllib.parse.urlparse,):
            for binary in (False, True):
                for raw, expected, category in [('65536', 'Port out of range 0-65535', 'too_high'), ('-1', None, 'negative'), ('foo', None, 'noninteger'), ('٦', None, 'unicode_digits')]:
                    if binary and category == 'unicode_digits':
                        continue
                    with self.subTest(api=parse.__name__, binary=binary, category=category):
                        url = 'http://example.test:' + raw + '/'
                        if binary:
                            url = url.encode('ascii')
                            raw = raw.encode('ascii')
                        message = expected or ('Port could not be cast to integer value as ' + repr(raw))
                        if category == 'too_high':
                            message = 'Port out of range 0-65534'
                        result = parse(url)
                        with self.assertRaises(ValueError) as caught:
                            result.port
                        error = caught.exception
                        self.assertIs(type(error), ValueError)
                        self.assertEqual(error.args, (message,))
                        self.assertEqual(str(error), message)

